function writeJsonWithHash(filename, data) {
  const fullPath = join(OUT_DIR, filename);
  const content = JSON.stringify(data, null, 2) + "\n";
  writeFileSync(fullPath, content, "utf8");
  const sha256 = createHash("sha256").update(content, "utf8").digest("hex");
  return { filename: `03-chemical-reach-cas/${filename}`, records: data.length, sha256 };
}

const f1 = writeJsonWithHash("chemical_regulatory_lists.json", chemicalRegulatoryLists);
const f2 = writeJsonWithHash("regulated_chemicals.json", regulatedChemicals);

const manifestPath = join(ROOT, "manifest.json");
const existingManifest = JSON.parse(readFileSync(manifestPath, "utf8"));

const datasetEntry = {
  module_id: "03-chemical-reach-cas",
  order: 3,
  title_tr: "Kimyasal Yasak & SDS (CAS Numarası) Takipçisi Veritabanı (REACH, SVHC, RoHS, POPs, TSCA, Prop 65, KKDİK)",
  title_en: "Industrial Chemical Restrictions & SDS CAS Tracker (ECHA SVHC, REACH XVII, RoHS, POPs, EPA TSCA, Prop 65)",
  authority: "ECHA (EU REACH/POPs/RoHS), US EPA (TSCA), California OEHHA (Prop 65) & T.C. ÇŞİDB (KKDİK)",
  official_sources: [
    "ECHA Candidate List of SVHC & Registry of Intentions (RoI)",
    "Regulation (EC) No 1907/2006 REACH Annex XVII (incl. PFHxA 2024/2462, Siloxanes 2024/1328, Formaldehyde 2023/1464)",
    "Directive 2011/65/EU & (EU) 2015/863 (RoHS 10 Substances) + Regulation (EU) 2019/1021 (POPs)",
    "US EPA TSCA Section 6 / 6(h) PBT Rules & California OEHHA Proposition 65 List",
    "ACS CAS Registry Number Mod-10 Checksum Standard & EINECS/ELINCS Mod-11 Checksum Standard",
  ],
  update_cadence: "biannual_jan_jun_plus_roi",
  verification_status: "verified",
  verified_at: new Date().toISOString(),
  collections: ["chemical_regulatory_lists", "regulated_chemicals"],
  files: [f1, f2],
};

const filtered = (existingManifest.datasets || []).filter((d) => d.module_id !== "03-chemical-reach-cas");
filtered.push(datasetEntry);
filtered.sort((a, b) => a.order - b.order);

const nextManifest = {
  ...existingManifest,
  updated_at: new Date().toISOString(),
  datasets: filtered,
};

writeFileSync(manifestPath, JSON.stringify(nextManifest, null, 2) + "\n", "utf8");
